Record Producto
  Define nombre As String;
  Define precio As Integer;
EndRecord

Algorithm Linea
  Define nombre As String;
  Define precio, cantidad As Integer;
  Read nombre;
  Read precio;
  Read cantidad;
  Define producto As Producto <- Producto(nombre, precio);
  Write producto.nombre, " x ", cantidad, " = ", producto.precio * cantidad;
EndAlgorithm
